@code {
    private AppointmentModel Model { get; set; } = new();

    private bool showStep2;
    private bool isChecking;
    private bool availabilityChecked;
    private bool submitted;

    private List<string> doctors = [];
    private List<string> timeSlots = [];
    private Dictionary<string, string> serverErrors = new();

    private EditContext? editContext;

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
    }

    private async Task ProceedToStep2()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        // Validate only step-1 fields
        editContext = new EditContext(Model);
        var validationMessages = new ValidationMessageStore(editContext);

        bool valid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
        {
            validationMessages.Add(() => Model.PatientName, "Patient name is required.");
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            validationMessages.Add(() => Model.Email, "Email is required.");
            valid = false;
        }
        else if (!new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(Model.Email))
        {
            validationMessages.Add(() => Model.Email, "Invalid email format.");
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            validationMessages.Add(() => Model.Phone, "Phone is required.");
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            validationMessages.Add(() => Model.InsuranceProvider, "Insurance provider is required.");
            valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (!valid)
            return;

        doctors = await AppointmentSvc.GetDoctorsAsync();
        showStep2 = true;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
        availabilityChecked = false;
    }

    private async Task LoadTimeSlots()
    {
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                Model.Doctor, DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        // Client-side validation of step-2 fields first
        editContext = new EditContext(Model);
        var msgs = new ValidationMessageStore(editContext);
        bool valid = true;

        if (string.IsNullOrWhiteSpace(Model.Doctor))
        {
            msgs.Add(() => Model.Doctor, "Please select a doctor.");
            valid = false;
        }
        if (!Model.AppointmentDate.HasValue)
        {
            msgs.Add(() => Model.AppointmentDate, "Date is required.");
            valid = false;
        }
        else if (Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            msgs.Add(() => Model.AppointmentDate, "Date must be in the future.");
            valid = false;
        }

        // Load time slots if needed
        if (valid)
        {
            await LoadTimeSlots();
        }

        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
        {
            msgs.Add(() => Model.TimeSlot, "Please select a time slot.");
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Reason))
        {
            msgs.Add(() => Model.Reason, "Reason for visit is required.");
            valid = false;
        }
        else if (Model.Reason.Length > 500)
        {
            msgs.Add(() => Model.Reason, "Reason must be 500 characters or fewer.");
            valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (!valid)
            return;

        // Server-side validation
        isChecking = true;
        try
        {
            serverErrors = await AppointmentSvc.ValidatePatientAsync(
                Model.Email,
                Model.InsuranceProvider,
                Model.Doctor,
                Model.TimeSlot);

            if (serverErrors.Count == 0)
            {
                availabilityChecked = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityChecked && serverErrors.Count == 0)
        {
            submitted = true;
        }
    }

    public class AppointmentModel
    {
        public string PatientName { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
        public string InsuranceProvider { get; set; } = "";
        public string Doctor { get; set; } = "";
        public DateTime? AppointmentDate { get; set; }
        public string TimeSlot { get; set; } = "";
        public string Reason { get; set; } = "";
    }
}

