+        }
+        else if (Model.AppointmentDate.Value.Date <= DateTime.Today)
+        {
+            msgs.Add(() => Model.AppointmentDate, "Date must be in the future.");
+            valid = false;
+        }
+
+        // Load time slots if needed
+        if (valid)
+        {
+            await LoadTimeSlots();
+        }
+
+        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
+        {
+            msgs.Add(() => Model.TimeSlot, "Please select a time slot.");
+            valid = false;
+        }
+        if (string.IsNullOrWhiteSpace(Model.Reason))
+        {
+            msgs.Add(() => Model.Reason, "Reason for visit is required.");
+            valid = false;
+        }
+        else if (Model.Reason.Length > 500)
+        {
+            msgs.Add(() => Model.Reason, "Reason must be 500 characters or fewer.");
+            valid = false;
+        }
+
+        editContext.NotifyValidationStateChanged();
+
+        if (!valid)
+            return;
+
+        // Server-side validation
+        isChecking = true;
+        try
+        {
+            serverErrors = await AppointmentSvc.ValidatePatientAsync(
+                Model.Email,
+                Model.InsuranceProvider,
+                Model.Doctor,
+                Model.TimeSlot);
+
+            if (serverErrors.Count == 0)
+            {
+                availabilityChecked = true;
+            }
+        }
+        finally
+        {
+            isChecking = false;
+        }
+    }
+
+    private void HandleSubmit()
+    {
+        if (availabilityChecked && serverErrors.Count == 0)
+        {
+            submitted = true;
+        }
+    }
+
+    public class AppointmentModel
+    {
+        public string PatientName { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+        public string InsuranceProvider { get; set; } = "";
+        public string Doctor { get; set; } = "";
+        public DateTime? AppointmentDate { get; set; }
+        public string TimeSlot { get; set; } = "";
+        public string Reason { get; set; } = "";
+    }
+}
